package com.billingcopilot.integration.jobber;
import com.billingcopilot.entity.JobberConnection;import com.billingcopilot.provider.jobber.JobberGraphQlClient;import com.billingcopilot.provider.jobber.JobberQueries;import com.billingcopilot.repository.JobberConnectionRepository;
import com.fasterxml.jackson.databind.JsonNode;import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.http.MediaType;import org.springframework.stereotype.Service;import org.springframework.util.LinkedMultiValueMap;import org.springframework.util.MultiValueMap;import org.springframework.web.client.RestClient;import org.springframework.web.util.UriComponentsBuilder;
import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.security.SecureRandom;import java.time.Instant;import java.util.Base64;import java.util.Map;
@Service
public class JobberOAuthService{
 private final JobberOAuthProperties p; private final PkceStore store; private final JobberConnectionRepository repo; private final JobberGraphQlClient gql; private final ObjectMapper om; private final RestClient rest=RestClient.create(); private final SecureRandom random=new SecureRandom();
 public JobberOAuthService(JobberOAuthProperties p,PkceStore store,JobberConnectionRepository repo,JobberGraphQlClient gql,ObjectMapper om){this.p=p;this.store=store;this.repo=repo;this.gql=gql;this.om=om;}
 public Map<String,Object> status(Long tenantId){var c=repo.findByTenantId(tenantId);return Map.of("configured",p.configured(),"connected",c.map(JobberConnection::isConnected).orElse(false),"mode",c.map(x->x.isConnected()?"jobber":"synthetic").orElse("synthetic"),"accountName",c.map(JobberConnection::getAccountName).orElse(""),"accountId",c.map(JobberConnection::getAccountId).orElse(""));}
 public String authorizationUrl(Long tenantId){if(!p.configured())throw new IllegalStateException("Jobber client credentials are not configured");String state=randomUrl(32),verifier=randomUrl(64),challenge=sha256Url(verifier);store.put(state,tenantId,verifier);return UriComponentsBuilder.fromUriString(p.authorizeUrl).queryParam("response_type","code").queryParam("client_id",p.clientId).queryParam("redirect_uri",p.redirectUri).queryParam("state",state).queryParam("code_challenge",challenge).queryParam("code_challenge_method","S256").build(true).toUriString();}
 public JobberConnection handleCallback(String code,String state){var e=store.remove(state);if(e==null)throw new IllegalArgumentException("Invalid or expired OAuth state");MultiValueMap<String,String> form=new LinkedMultiValueMap<>();form.add("client_id",p.clientId);form.add("client_secret",p.clientSecret);form.add("grant_type","authorization_code");form.add("code",code);form.add("redirect_uri",p.redirectUri);form.add("code_verifier",e.verifier());String body=rest.post().uri(p.tokenUrl).contentType(MediaType.APPLICATION_FORM_URLENCODED).body(form).retrieve().body(String.class);try{JsonNode n=om.readTree(body);String access=n.path("access_token").asText();String refresh=n.path("refresh_token").asText();if(access.isBlank()||refresh.isBlank())throw new IllegalStateException("OAuth response did not include required tokens");long expires=n.path("expires_in").asLong(3600);String accountJson=gql.execute(access,JobberQueries.ACCOUNT,Map.of());JsonNode account=om.readTree(accountJson).path("data").path("account");JobberConnection c=repo.findByTenantId(e.tenantId()).orElseGet(JobberConnection::new);c.setTenantId(e.tenantId());c.setAccessToken(access);c.setRefreshToken(refresh);c.setAccessTokenExpiresAt(Instant.now().plusSeconds(expires));if(account.path("id").asText().isBlank())throw new IllegalStateException("Jobber account lookup returned no ID");c.setAccountId(account.path("id").asText());c.setAccountName(account.path("name").asText());c.setConnected(true);c.setUpdatedAt(Instant.now());return repo.save(c);}catch(Exception ex){throw new IllegalStateException("Unable to complete Jobber OAuth",ex);}}
 private String randomUrl(int bytes){byte[] b=new byte[bytes];random.nextBytes(b);return Base64.getUrlEncoder().withoutPadding().encodeToString(b);} private String sha256Url(String s){try{return Base64.getUrlEncoder().withoutPadding().encodeToString(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.US_ASCII)));}catch(Exception e){throw new IllegalStateException(e);}}
}
